package example
type Item struct { Value int }
func Greet() int { return 1 }

resource "example_item" "demo" {
  value = "hello"
}

package example

class Item {
    val value = 1
    fun greet(): Int {
        return value
    }
}

@interface Item
- (int)greet;
@end
@implementation Item
- (int)greet { return 1; }
@end
int outer(int x) {
    int (^f)(int) = ^(int y) { return inside(x + y); };
    return f(1);
}

DECLARE value integer := 1;
BEGIN
 IF value > 0 THEN value := value + 1; END IF;
END;

syntax = "proto3";
package example;
message Item { int32 value = 1; }

class Item:
    def greet(self):
        return "Olá"
